import React from 'react';

import clsx from 'clsx';
import { Link } from 'react-router-dom';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import PageLoader from '@components/PageLoader';
import { get } from '@helpers/httpClient';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohCard from '@ui-kit/Card';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IHikingObservationsProps {
  id_hiking: number;
}

const HikingObservations: React.FC<IHikingObservationsProps> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();

  const [data, setData] = React.useState<any[]>([]);

  const hikingData = React.useContext(HikingContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const hd = await get(`/ajax/users/inaturalist_observations.php`, {
          photos: true,
          user_login: hikingData?.hikers
            .filter((x) => x.inaturalist_login?.length)
            .map((x) => x.inaturalist_login)
            .join(','),
          d1: hikingData?.start.toISOString(),
          d2: hikingData?.finish.toISOString(),
        });
        setData(hd.results);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [hikingData?.hikers, id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData) {
    return <PohAlert variant={AlertVariant.Danger}>no hikingData</PohAlert>;
  }
  return (
    <section>
      <p className="text-muted mt-n3">
        Сюда попадают наблюдения, зафиксированные с {hikingData.start.toLocaleString()} по{' '}
        {hikingData.finish.toLocaleString()}, от участников похода, у которых в{' '}
        <Link to="/profile">профиле</Link> добавлено имя пользователя сервиса{' '}
        <a href="https://www.inaturalist.org/" target="_blank" rel="noreferrer">
          iNaturalist
        </a>
        .
      </p>
      <PohRow>
        {data.map((obs) => {
          return (
            <PohCol sm={3} key={obs.id}>
              <PohCard
                className={clsx(
                  'mb-3',
                  obs.identifications?.some?.((idt: any) => idt?.taxon?.conservation_status) &&
                    'border border-danger',
                )}
                img={obs.observation_photos[0].photo.url.replace('square', 'medium')}
                title={obs.species_guess ?? '?'}
                subtitle={obs.taxon.name}
                footer={
                  <div className="d-flex align-items-center" style={{ lineHeight: 0.9 }}>
                    {new Date(obs.time_observed_at).toLocaleString()}

                    <div className="d-flex justify-content-end w-50 text-end align-items-center">
                      {obs.user.name}
                      <PohAva colorize className="ms-2" src={obs.user.icon} alt={obs.user.name} />
                    </div>
                  </div>
                }
                links={[
                  <a href={obs.uri} key={obs.uri} target="_blank" rel="noreferrer">
                    Подробнее
                  </a>,
                ]}
                text={obs.description}
              />
            </PohCol>
          );
        })}
      </PohRow>
    </section>
  );
};

export default HikingObservations;
